/* 发送方: audio -> idx (留在内存). 返回 padded 长度 T0; *pidx 由调用方释放. */
static int encode_to_idx(const float *audio, int origT, int *pTt, int64_t **pidx) {
    int T0; float *padded = preprocess(audio, origT, &T0);
    int Tt = T0 / HOP_LENGTH;
    const int B = 1;

    T xin = t_alloc(3, (int[]){B, 1, T0});
    for (int t = 0; t < T0; t++) xin.d[t] = padded[t];

    T enc = t_alloc(3, (int[]){B, FEATURE_DIM, Tt});
    encoder_forward(&xin, &enc);

    T enenc = t_alloc(3, (int[]){B, Tt, FEATURE_DIM});
    en_encoder_forward(&enc, &enenc);

    /* 压缩路径下, en_encoder 已将时序压缩到 Tt/EN_ENC_COMPRESS_RATE, 潜在 token 数须用该值 */
    int Tlat = Tt / EN_ENC_COMPRESS_RATE;
    int64_t *idx = (int64_t*)malloc(sizeof(int64_t) * (size_t)B * Tlat);
    T enq = t_alloc(3, (int[]){B, Tlat, FEATURE_DIM});
    quantizer_forward(&enenc, &enq, idx, Tlat);

    t_free(&xin); t_free(&enc); t_free(&enenc); t_free(&enq);
    free(padded);
    *pTt = Tt; *pidx = idx;
    return T0;
}

/* 接收方: idx -> audio (前 origT 个样本). *pout 由调用方释放. 返回 padded 长度 T0. */
static int decode_from_idx(const int64_t *idx, int Tt, int origT, float **pout) {
    const int B = 1;
    int Tlat = Tt / EN_ENC_COMPRESS_RATE;   /* 潜在 token 数 (压缩路径下 < Tt) */
    T enq = t_alloc(3, (int[]){B, Tlat, FEATURE_DIM});
    quantizer_to_features(idx, &enq, Tlat);

    T endec = t_alloc(3, (int[]){B, FEATURE_DIM, Tt});
    en_decoder_forward(&enq, &endec);

    int T0 = Tt * HOP_LENGTH;
    T dec = t_alloc(3, (int[]){B, 1, T0});
    decoder_forward(&endec, &dec);

    float *out = (float*)malloc(sizeof(float) * origT);
    for (int i = 0; i < origT; i++) out[i] = dec.d[i];

    t_free(&enq); t_free(&endec); t_free(&dec);
    *pout = out;
    return T0;
}

/* loop 模式: 进程内 audio -> idx -> audio (等价于 send+recv, 供对照) */
static int run_loop(const char *in_wav, const char *out_wav) {
    float *audio; int origT;
    if (read_wav(in_wav, &audio, &origT) != 0) return 1;
    int Tt; int64_t *idx;
    encode_to_idx(audio, origT, &Tt, &idx);
    float *rec;
    decode_from_idx(idx, Tt, origT, &rec);
    write_wav(out_wav, rec, origT);
    fprintf(stderr, "[ok][loop] %s -> %s  orig=%d Tt=%d tokens\n", in_wav, out_wav, origT, Tt);
    free(audio); free(idx); free(rec);
    return 0;
}

/* send 模式: 音频 -> idx 文件 (只产出传输用的 idx) */
static int run_send(const char *in_wav, const char *idx_path) {
