            ch=fmt[2]|(fmt[3]<<8);
            sr=fmt[4]|(fmt[5]<<8)|(fmt[6]<<16)|((unsigned)fmt[7]<<24);
            bits=fmt[14]|(fmt[15]<<8);
            int rem=(int)sz-16; if (rem>0) fseek(f,rem,SEEK_CUR);
        } else if (!memcmp(ck,"data",4)) {
            unsigned frames = sz/(2u*(unsigned)ch);
            float *buf = (float*)malloc(sizeof(float)*frames);
            for (unsigned i=0;i<frames;i++) {
                int s=0; for (int c=0;c<ch;c++){ short v; if(fread(&v,2,1,f)!=1){fclose(f);return -1;} s+=v; }
                buf[i]=(s/(float)ch)/32768.0f;
            }
            fclose(f);
            if (sr!=16000) fprintf(stderr,"[warn] sr=%d\n", sr);
            *out=buf; *orig_len=(int)frames; return 0;
        } else fseek(f,(long)sz,SEEK_CUR);
    }
    fclose(f); return -1;
}

static float* preprocess(const float *a, int len, int *out_len) {
    int frame = HOP_LENGTH * EN_ENC_COMPRESS_RATE;
    int pad = (frame - (len % frame)) % frame;
    int n = len + pad;
    float *buf = (float*)malloc(sizeof(float)*n);
    for (int i=0;i<len;i++) buf[i]=a[i];
    for (int i=len;i<n;i++) buf[i]=0.0f;
    *out_len=n; return buf;
}

int main(int argc, char **argv) {
