/* macs_count.c - exact multiply-accumulate census for one encode+decode pass.
 *
 * Counts the dense math that dominates the ESP32-S3 budget:
 *   linear / conv1d / conv1d_d / conv1d_dw   via GNU ld --wrap
 *   QK^T and attn.V inside local_mha_layer    via -DCOUNT_MACS (transformer.c)
 * Elementwise work (snake, norms, GELU, softmax, trend-pool) is NOT counted.
 *
 * Build with -DCOUNT_MACS and -Wl,--wrap=... (see build_win.ps1 macs target).
 */
#include "nn_infer.h"
#include "fsq_codec.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

/* counters defined here, filled by the wrappers below */
static long long mac_linear = 0, mac_conv1d = 0, mac_conv1d_d = 0, mac_dw = 0, mac_up = 0;

/* attention counters live in transformer.c under COUNT_MACS */
extern long long g_attn_macs;
extern long long g_attn_dpb;
extern int       g_attn_heads;

static double now_s(void) { return (double)clock() / (double)CLOCKS_PER_SEC; }

int __real_linear(const float *W, const float *b, const T *x, T *y, int in, int out);
void __real_conv1d(const float *W, const float *b, const T *x, T *y,
                   int Ci, int Co, int k, int stride, int pad, int groups, int T_in);
void __real_conv1d_d(const float *W, const float *b, const T *x, T *y,
                     int Ci, int Co, int k, int stride, int pad, int groups, int T_in, int dil);
void __real_conv1d_dw(const float *W, const float *b, const T *x, T *y, int C, int k, int stride, int pad, int T_in);
void __real_upsampling_linear(const T *x, T *y, int B, int C, int Tin, int scale);

int __wrap_linear(const float *W, const float *b, const T *x, T *y, int in, int out) {
    mac_linear += (long long)(x->len / in) * out * in;
    return __real_linear(W, b, x, y, in, out);
}
void __wrap_conv1d(const float *W, const float *b, const T *x, T *y,
                   int Ci, int Co, int k, int stride, int pad, int groups, int T_in) {
    int T_out = (T_in + 2 * pad - k) / stride + 1;
    mac_conv1d += (long long)x->shape[0] * Co * T_out * (Ci / groups) * k;
    __real_conv1d(W, b, x, y, Ci, Co, k, stride, pad, groups, T_in);
}
void __wrap_conv1d_d(const float *W, const float *b, const T *x, T *y,
                     int Ci, int Co, int k, int stride, int pad, int groups, int T_in, int dil) {
    int T_out = (T_in + 2 * pad - dil * (k - 1) - 1) / stride + 1;
    mac_conv1d_d += (long long)x->shape[0] * Co * T_out * (Ci / groups) * k;
    __real_conv1d_d(W, b, x, y, Ci, Co, k, stride, pad, groups, T_in, dil);
}
void __wrap_conv1d_dw(const float *W, const float *b, const T *x, T *y, int C, int k, int stride, int pad, int T_in) {
    int T_out = (T_in + 2 * pad - k) / stride + 1;
    mac_dw += (long long)x->shape[0] * C * T_out * k;
    __real_conv1d_dw(W, b, x, y, C, k, stride, pad, T_in);
}
void __wrap_upsampling_linear(const T *x, T *y, int B, int C, int Tin, int scale) {
    mac_up += (long long)B * C * Tin * scale * 2;
    __real_upsampling_linear(x, y, B, C, Tin, scale);
}

static int read_wav(const char *path, float **out, int *orig_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "[err] cannot open %s\n", path); return -1; }
    unsigned char h[12];
    if (fread(h,1,12,f)!=12 || memcmp(h,"RIFF",4) || memcmp(h+8,"WAVE",4)) { fclose(f); return -1; }
    int sr=0,ch=0,bits=0; unsigned char ck[8];
    while (fread(ck,1,8,f)==8) {
