                buf[i]=(s/(float)ch)/32768.0f;
            }
            fclose(f);
            if (sr!=16000) fprintf(stderr,"[warn] sr=%d\n", sr);
            *out=buf; *orig_len=(int)frames; return 0;
        } else fseek(f,(long)sz,SEEK_CUR);
    }
    fclose(f); return -1;
}

int main(int argc, char **argv) {
    const char *wav = (argc>1)? argv[1] : "libri0.wav";
    float *audio; int origT;
    if (read_wav(wav,&audio,&origT)!=0) return 1;

    int frame = HOP_LENGTH * EN_ENC_COMPRESS_RATE;
    int pad = (frame - (origT % frame)) % frame;
    int T0 = origT + pad;
    float *padded = (float*)malloc(sizeof(float)*T0);
    for (int i=0;i<origT;i++) padded[i]=audio[i];
    for (int i=origT;i<T0;i++) padded[i]=0.0f;
    int Tt = T0 / HOP_LENGTH, Tlat = Tt / EN_ENC_COMPRESS_RATE;
    const int B = 1;
    double dur = (double)origT/16000.0;

    /* ---- encode ---- */
    long long a0 = mac_linear, c0 = mac_conv1d, d0 = mac_conv1d_d, w0 = mac_dw, u0 = mac_up, at0 = g_attn_macs, dp0 = g_attn_dpb;
    T xin = t_alloc(3,(int[]){B,1,T0});
    for (int i=0;i<T0;i++) xin.d[i]=padded[i];
    T enc = t_alloc(3,(int[]){B,FEATURE_DIM,Tt});
    encoder_forward(&xin,&enc);
    long long a1=mac_linear,c1=mac_conv1d,d1=mac_conv1d_d,w1=mac_dw,u1=mac_up,at1=g_attn_macs,dp1=g_attn_dpb;
    T enenc = t_alloc(3,(int[]){B,Tt,FEATURE_DIM});
    en_encoder_forward(&enc,&enenc);
    long long a2=mac_linear,c2=mac_conv1d,d2=mac_conv1d_d,w2=mac_dw,u2=mac_up,at2=g_attn_macs,dp2=g_attn_dpb;
    int64_t *idx = (int64_t*)malloc(sizeof(int64_t)*(size_t)Tlat);
    T enq = t_alloc(3,(int[]){B,Tlat,FEATURE_DIM});
    quantizer_forward(&enenc,&enq,idx,Tlat);

    /* ---- decode ---- */
    T enq2 = t_alloc(3,(int[]){B,Tlat,FEATURE_DIM});
    quantizer_to_features(idx,&enq2,Tlat);
    long long a3=mac_linear,c3=mac_conv1d,d3=mac_conv1d_d,w3=mac_dw,u3=mac_up,at3=g_attn_macs,dp3=g_attn_dpb;
    T endec = t_alloc(3,(int[]){B,FEATURE_DIM,Tt});
    en_decoder_forward(&enq2,&endec);
    long long a4=mac_linear,c4=mac_conv1d,d4=mac_conv1d_d,w4=mac_dw,u4=mac_up,at4=g_attn_macs,dp4=g_attn_dpb;
    T dec = t_alloc(3,(int[]){B,1,T0});
