    long long a5=mac_linear,c5=mac_conv1d,d5=mac_conv1d_d,w5=mac_dw,u5=mac_up,at5=g_attn_macs,dp5=g_attn_dpb;

    double tot = dur;
    #define MM(x) ((double)(x)/1e6)
