/* attn_count.c - authoritative attention MAC census (needs -DCOUNT_MACS).
 * transformer.c accumulates QK^T / attn.V in g_attn_macs and the dynamic
 * position-bias MLP in g_attn_dpb. Everything else is counted analytically by
 * test/mac_census.py, which this program cross-checks.
 */
#include "nn_infer.h"
#include "fsq_codec.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern long long g_attn_macs;
extern long long g_attn_dpb;
extern int       g_attn_heads;

static int read_wav(const char *path, float **out, int *orig_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "[err] cannot open %s\n", path); return -1; }
    unsigned char h[12];
    if (fread(h,1,12,f)!=12 || memcmp(h,"RIFF",4) || memcmp(h+8,"WAVE",4)) { fclose(f); return -1; }
    int sr=0,ch=0,bits=0; unsigned char ck[8];
    while (fread(ck,1,8,f)==8) {
        unsigned int sz = ck[4]|(ck[5]<<8)|(ck[6]<<16)|((unsigned)ck[7]<<24);
        if (!memcmp(ck,"fmt ",4)) {
            unsigned char fmt[16];
            if (fread(fmt,1,16,f)!=16) { fclose(f); return -1; }
            ch=fmt[2]|(fmt[3]<<8);
            sr=fmt[4]|(fmt[5]<<8)|(fmt[6]<<16)|((unsigned)fmt[7]<<24);
            bits=fmt[14]|(fmt[15]<<8);
            int rem=(int)sz-16; if (rem>0) fseek(f,rem,SEEK_CUR);
        } else if (!memcmp(ck,"data",4)) {
            unsigned frames = sz/(2u*(unsigned)ch);
            float *buf = (float*)malloc(sizeof(float)*frames);
            for (unsigned i=0;i<frames;i++) {
                int s=0; for (int c=0;c<ch;c++){ short v; if(fread(&v,2,1,f)!=1){fclose(f);return -1;} s+=v; }
                buf[i]=(s/(float)ch)/32768.0f;
            }
            fclose(f);
            if (sr!=16000) fprintf(stderr,"[warn] sr=%d\n", sr);
            *out=buf; *orig_len=(int)frames; return 0;
        } else fseek(f,(long)sz,SEEK_CUR);
    }
    fclose(f); return -1;
}

int main(int argc, char **argv) {
    const char *wav = (argc>1)? argv[1] : "libri0.wav";
    float *audio; int origT;
    if (read_wav(wav,&audio,&origT)!=0) return 1;

    int frame = HOP_LENGTH * EN_ENC_COMPRESS_RATE;
    int pad = (frame - (origT % frame)) % frame;
    int T0 = origT + pad;
    float *padded = (float*)malloc(sizeof(float)*T0);
    for (int i=0;i<origT;i++) padded[i]=audio[i];
    for (int i=origT;i<T0;i++) padded[i]=0.0f;
    int Tt = T0 / HOP_LENGTH, Tlat = Tt / EN_ENC_COMPRESS_RATE;
    const int B = 1;
    double dur = (double)origT/16000.0;

    T xin = t_alloc(3,(int[]){B,1,T0});
    for (int i=0;i<T0;i++) xin.d[i]=padded[i];
    T enc = t_alloc(3,(int[]){B,FEATURE_DIM,Tt});
    encoder_forward(&xin,&enc);

    long long q0 = g_attn_macs, p0 = g_attn_dpb;
    T enenc = t_alloc(3,(int[]){B,Tt,FEATURE_DIM});
    en_encoder_forward(&enc,&enenc);
    long long q1 = g_attn_macs, p1 = g_attn_dpb;

    int64_t *idx = (int64_t*)malloc(sizeof(int64_t)*(size_t)Tlat);
    T enq = t_alloc(3,(int[]){B,Tlat,FEATURE_DIM});
    quantizer_forward(&enenc,&enq,idx,Tlat);

    T enq2 = t_alloc(3,(int[]){B,Tlat,FEATURE_DIM});
    quantizer_to_features(idx,&enq2,Tlat);
    long long q2 = g_attn_macs, p2 = g_attn_dpb;
    T endec = t_alloc(3,(int[]){B,FEATURE_DIM,Tt});
    en_decoder_forward(&enq2,&endec);
    long long q3 = g_attn_macs, p3 = g_attn_dpb;

    T dec = t_alloc(3,(int[]){B,1,T0});
    decoder_forward(&endec,&dec);

    printf("=== attention MAC census  (feature_dim=%d hop=%d heads=%d) ===\n", FEATURE_DIM, HOP_LENGTH, g_attn_heads);
    printf("audio %.3f s  T0=%d Tt=%d Tlat=%d  (%.1f tok/s)\n\n", dur, T0, Tt, Tlat, Tlat/dur);
    printf("%-16s %14s %14s %14s\n", "stage", "QK+AV MMAC", "dynpos MMAC", "MMAC/s");
    printf("%-16s %14.1f %14.1f %14.1f\n", "en_encoder", (q1-q0)/1e6, (p1-p0)/1e6, ((q1-q0)+(p1-p0))/1e6/dur);
    printf("%-16s %14.1f %14.1f %14.1f\n", "en_decoder", (q3-q2)/1e6, (p3-p2)/1e6, ((q3-q2)+(p3-p2))/1e6/dur);
    printf("%-16s %14.1f %14.1f %14.1f\n", "attn TOTAL", (q3-q0)/1e6, (p3-p0)/1e6, ((q3-q0)+(p3-p0))/1e6/dur);
    printf("\ndynpos / (QK+AV) = %.2fx   -> caching the bias table removes the dynpos term\n",
           (double)(p3-p0)/(double)((q3-q0)?(q3-q0):1));
    return 0;
}
